import { db } from "../db.js";
import { favoriteSchema } from "../validation.js";
export function getFavorites(req, res, next) {
  db.sql`SELECT * FROM favorites WHERE user_id = ${req.user.id}`
    .then((rows) => {
      res.json(rows);
    })
    .catch((err) => {
      next(err);
    });
